    void deveIgnorarTokenNoCadastro() {
        MockHttpServletRequest request = new MockHttpServletRequest("POST", "/api/users");
        request.addHeader("Authorization", "Token abc");

        assertThat(resolver.resolve(request)).isNull();
    }

