    void deveUsarJsonUtf8No200() throws Exception {
        String username = "ct-" + UUID.randomUUID().toString().substring(0, 8);
        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpoCadastro(username)))
                .andExpect(status().isCreated());

        mockMvc.perform(get("/api/profiles/{username}", username))
                .andExpect(status().isOk())
                .andExpect(JSON_UTF8);
