    void deveUsarJsonUtf8No404() throws Exception {
        mockMvc.perform(get("/api/profiles/{username}", "ninguem-" + UUID.randomUUID()))
                .andExpect(status().isNotFound())
                .andExpect(JSON_UTF8);
    }

    @Test
    void deveUsarJsonUtf8No409() throws Exception {
        String username = "ct-" + UUID.randomUUID().toString().substring(0, 8);
        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpoCadastro(username)))
                .andExpect(status().isCreated());

        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpoCadastro(username)))
