package com.example.blog.shared;

import static org.hamcrest.Matchers.matchesPattern;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.blog.TestcontainersConfiguration;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultMatcher;

/**
 * Todas as respostas com corpo usam {@code application/json; charset=utf-8} (FR-027), inclusive as de erro.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Import(TestcontainersConfiguration.class)
class ContentTypeIT {

    private static final ResultMatcher JSON_UTF8 =
            header().string("Content-Type", matchesPattern("(?i)application/json;\\s*charset=utf-8"));

    @Autowired
    private MockMvc mockMvc;

    private String corpoCadastro(String username) {
        return """
                {"user":{"username":"%s","email":"%s@exemplo.test","password":"senha-ficticia"}}"""
                .formatted(username, username);
    }

    @Test
    void deveUsarJsonUtf8No201() throws Exception {
        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON)
                        .content(corpoCadastro("ct-" + UUID.randomUUID().toString().substring(0, 8))))
                .andExpect(status().isCreated())
                .andExpect(JSON_UTF8);
    }

    @Test
    void deveUsarJsonUtf8No200() throws Exception {
        String username = "ct-" + UUID.randomUUID().toString().substring(0, 8);
        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpoCadastro(username)))
                .andExpect(status().isCreated());

        mockMvc.perform(get("/api/profiles/{username}", username))
                .andExpect(status().isOk())
                .andExpect(JSON_UTF8);
    }

    @Test
    void deveUsarJsonUtf8No401DoEntryPoint() throws Exception {
        mockMvc.perform(get("/api/user"))
                .andExpect(status().isUnauthorized())
                .andExpect(JSON_UTF8);
    }

    @Test
    void deveUsarJsonUtf8No404() throws Exception {
        mockMvc.perform(get("/api/profiles/{username}", "ninguem-" + UUID.randomUUID()))
                .andExpect(status().isNotFound())
                .andExpect(JSON_UTF8);
    }

    @Test
    void deveUsarJsonUtf8No409() throws Exception {
        String username = "ct-" + UUID.randomUUID().toString().substring(0, 8);
        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpoCadastro(username)))
                .andExpect(status().isCreated());

        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpoCadastro(username)))
                .andExpect(status().isConflict())
                .andExpect(JSON_UTF8);
    }

    @Test
    void deveUsarJsonUtf8No422() throws Exception {
        mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content("{"))
                .andExpect(status().isUnprocessableContent())
                .andExpect(JSON_UTF8);
    }
}
